using System;
using System.Collections.Generic;
using UnityEngine;

namespace Undercurrent.Runtime.Services
{
    /// <summary>
    /// Synthesises every placeholder sound and music loop at startup. All audio is generated by this code, so it is
    /// original and license-free. It is functional placeholder audio, not final production sound design; replace by
    /// dropping licensed clips into Resources/Undercurrent/Audio with the same ids (see README).
    /// </summary>
    public static class ProceduralAudio
    {
        public const int SampleRate = 22050;

        public static Dictionary<string, AudioClip> BuildLibrary()
        {
            var lib = new Dictionary<string, AudioClip>();
            void Add(string id, float[] data) => lib[id] = ToClip(id, data);

            Add("impact_light", Impact(0.09f, 140f, 0.55f, 4200f, 1));
            Add("impact_heavy", Impact(0.18f, 85f, 0.8f, 2600f, 2));
            Add("impact_special", Special());
            Add("block", Block());
            Add("parry", Parry());
            Add("whoosh_light", Whoosh(0.12f, 2600f, 0.35f, 3));
            Add("whoosh_heavy", Whoosh(0.2f, 1500f, 0.5f, 4));
            Add("dodge", Whoosh(0.18f, 1100f, 0.3f, 5));
            Add("footstep", Impact(0.05f, 70f, 0.25f, 900f, 6));
            Add("throw_slam", Impact(0.32f, 55f, 1.0f, 1500f, 7));
            Add("effort", Breath(0.16f, 8));
            Add("effort_heavy", Breath(0.26f, 9));
            Add("hurt", Breath(0.22f, 10, low: true));
            Add("ui_click", Tone(0.035f, new[] { 1800f }, 0.25f, 60f));
            Add("ui_confirm", Chime(new[] { 880f, 1320f }, 0.09f));
            Add("ui_back", Chime(new[] { 990f, 660f }, 0.08f));
            Add("round_bell", Tone(1.4f, new[] { 640f, 1290f, 1710f, 2470f }, 0.45f, 2.6f));
            Add("ko", Ko());
            Add("victory", Chime(new[] { 523f, 659f, 784f, 1046f }, 0.18f));
            Add("defeat", Chime(new[] { 392f, 330f, 262f }, 0.25f));
            Add("special_ready", Chime(new[] { 1046f, 1568f }, 0.07f));
            Add("guard_break", GuardBreak());
            Add("blade_light", Blade(0.12f, 2200f, 0.55f, 71));
            Add("blade_heavy", Blade(0.22f, 1500f, 0.8f, 72));
            Add("clash", Clash());
            Add("disarm", Clatter());

            Add("amb_harbor", Ambience(8f, 400f, 0.18f, 0f, 11));
            Add("amb_rain", Ambience(8f, 6000f, 0.12f, 0.6f, 12));
            Add("amb_drips", Drips(8f, 13));

            Add("music_menu", Music(84, new[] { 0, 0, 3, 5 }, 41, 0.6f, 21));
            Add("music_pulse", Music(100, new[] { 0, 0, 5, 3 }, 38, 0.8f, 22));
            Add("music_drive", Music(112, new[] { 0, 3, 7, 5 }, 40, 0.9f, 23));
            Add("music_boss", Music(124, new[] { 0, 1, 0, 6 }, 36, 1.0f, 24));
            return lib;
        }

        private static AudioClip ToClip(string id, float[] data)
        {
            var clip = AudioClip.Create(id, data.Length, 1, SampleRate, false);
            clip.SetData(data, 0);
            return clip;
        }

        private static float[] Buffer(float seconds) => new float[Mathf.Max(1, (int)(seconds * SampleRate))];

        private static float Lowpass(ref float state, float input, float cutoff)
        {
            float rc = 1f / (2f * Mathf.PI * cutoff);
            float dt = 1f / SampleRate;
            float a = dt / (rc + dt);
            state += a * (input - state);
            return state;
        }

        private static void Normalize(float[] d, float peak)
        {
            float max = 0.0001f;
            foreach (var s in d) max = Mathf.Max(max, Mathf.Abs(s));
            float k = peak / max;
            for (int i = 0; i < d.Length; i++) d[i] *= k;
        }

        private static float[] Impact(float seconds, float thumpHz, float peak, float noiseCutoff, int seed)
        {
            var rng = new System.Random(seed);
            var d = Buffer(seconds);
            float lp = 0f;
            for (int i = 0; i < d.Length; i++)
            {
                float t = (float)i / SampleRate;
                float env = Mathf.Exp(-t * 28f / seconds * 0.12f * 10f);
                float pitch = thumpHz * (1f + 1.5f * Mathf.Exp(-t * 60f));
                float thump = Mathf.Sin(2f * Mathf.PI * pitch * t) * Mathf.Exp(-t * 18f);
                float noise = Lowpass(ref lp, (float)(rng.NextDouble() * 2 - 1), noiseCutoff) * Mathf.Exp(-t * 45f);
                d[i] = (thump * 0.8f + noise * 1.2f) * env;
            }
            Normalize(d, peak);
            return d;
        }

        private static float[] Special()
        {
            var a = Impact(0.45f, 60f, 1f, 3000f, 31);
            for (int i = 0; i < a.Length; i++)
            {
                float t = (float)i / SampleRate;
                a[i] += 0.35f * Mathf.Sin(2f * Mathf.PI * (900f - 600f * t) * t) * Mathf.Exp(-t * 6f);
            }
            Normalize(a, 1f);
            return a;
        }

        private static float[] Block()
        {
            var rng = new System.Random(41);
            var d = Buffer(0.08f);
            float lp = 0f;
            for (int i = 0; i < d.Length; i++)
            {
                float t = (float)i / SampleRate;
                float n = (float)(rng.NextDouble() * 2 - 1);
                float hp = n - Lowpass(ref lp, n, 1200f);
                d[i] = hp * Mathf.Exp(-t * 70f) + 0.5f * Mathf.Sin(2f * Mathf.PI * 420f * t) * Mathf.Exp(-t * 50f);
            }
            Normalize(d, 0.6f);
            return d;
        }

        private static float[] Parry()
        {
            var d = Buffer(0.5f);
            float[] partials = { 1180f, 1873f, 2640f, 3510f };
            for (int i = 0; i < d.Length; i++)
            {
                float t = (float)i / SampleRate;
                float s = 0f;
                for (int p = 0; p < partials.Length; p++) s += Mathf.Sin(2f * Mathf.PI * partials[p] * t) * Mathf.Exp(-t * (6f + p * 3f)) / (p + 1);
                d[i] = s;
            }
            Normalize(d, 0.6f);
            return d;
        }

        private static float[] GuardBreak()
        {
            var a = Parry();
            var b = Impact(0.5f, 70f, 1f, 2000f, 51);
            var d = Buffer(0.5f);
            for (int i = 0; i < d.Length; i++) d[i] = (i < a.Length ? a[i] * 0.6f : 0f) + (i < b.Length ? b[i] : 0f);
            Normalize(d, 0.9f);
            return d;
        }

        /// <summary>Blade impact: a slicing swish plus a short metallic ring.</summary>
        private static float[] Blade(float seconds, float swishHz, float peak, int seed)
        {
            var swish = Whoosh(seconds, swishHz, 1f, seed);
            var ring = Tone(seconds, new[] { 2900f, 4100f }, 1f, 22f);
            var hit = Impact(seconds, 110f, 1f, 3000f, seed + 1);
            var d = Buffer(seconds);
            for (int i = 0; i < d.Length; i++)
                d[i] = (i < swish.Length ? swish[i] * 0.6f : 0f) + (i < ring.Length ? ring[i] * 0.25f : 0f) + (i < hit.Length ? hit[i] * 0.5f : 0f);
            Normalize(d, peak);
            return d;
        }

        /// <summary>Two blades meeting: bright inharmonic ring with a sharp attack.</summary>
        private static float[] Clash()
        {
            var d = Buffer(0.9f);
            float[] partials = { 1650f, 2470f, 3320f, 4890f, 6150f };
            var rng = new System.Random(81);
            for (int i = 0; i < d.Length; i++)
            {
                float t = (float)i / SampleRate;
                float s = 0f;
                for (int p = 0; p < partials.Length; p++) s += Mathf.Sin(2f * Mathf.PI * partials[p] * t) * Mathf.Exp(-t * (4f + p * 2.5f)) / (p + 1);
                s += (float)(rng.NextDouble() * 2 - 1) * Mathf.Exp(-t * 90f) * 0.8f;
                d[i] = s;
            }
            Normalize(d, 0.85f);
            return d;
        }

        /// <summary>A weapon clattering on the floor: a few decaying metallic bounces.</summary>
        private static float[] Clatter()
        {
            var d = Buffer(0.8f);
            float[] times = { 0f, 0.16f, 0.29f, 0.38f, 0.44f };
            for (int b = 0; b < times.Length; b++)
            {
                int start = (int)(times[b] * SampleRate);
                float amp = 1f / (b + 1);
                for (int i = start; i < d.Length; i++)
                {
                    float t = (float)(i - start) / SampleRate;
                    d[i] += amp * (Mathf.Sin(2f * Mathf.PI * (2300f + 300f * b) * t) + 0.5f * Mathf.Sin(2f * Mathf.PI * 3700f * t)) * Mathf.Exp(-t * 30f);
                }
            }
            Normalize(d, 0.6f);
            return d;
        }

        private static float[] Whoosh(float seconds, float centre, float peak, int seed)
        {
            var rng = new System.Random(seed);
            var d = Buffer(seconds);
            float lp1 = 0f, lp2 = 0f;
            for (int i = 0; i < d.Length; i++)
            {
                float t = (float)i / d.Length;
                float n = (float)(rng.NextDouble() * 2 - 1);
                float band = Lowpass(ref lp1, n, centre * (0.6f + t)) - Lowpass(ref lp2, n, centre * 0.25f);
                d[i] = band * Mathf.Sin(Mathf.PI * t);
            }
            Normalize(d, peak);
            return d;
        }

        /// <summary>Breathy exhale used as a placeholder effort vocal (no recorded voice is shipped).</summary>
        private static float[] Breath(float seconds, int seed, bool low = false)
        {
            var rng = new System.Random(seed);
            var d = Buffer(seconds);
            float lp = 0f, lp2 = 0f;
            float f1 = low ? 500f : 750f;
            for (int i = 0; i < d.Length; i++)
            {
                float t = (float)i / d.Length;
                float n = (float)(rng.NextDouble() * 2 - 1);
                float shaped = Lowpass(ref lp, n, f1 * 2.4f) - Lowpass(ref lp2, n, f1 * 0.5f);
                float env = Mathf.Sin(Mathf.PI * Mathf.Pow(t, 0.5f)) * (1f - t);
                d[i] = shaped * env;
            }
            Normalize(d, 0.35f);
            return d;
        }

        private static float[] Tone(float seconds, float[] freqs, float peak, float decay)
        {
            var d = Buffer(seconds);
            for (int i = 0; i < d.Length; i++)
            {
                float t = (float)i / SampleRate;
                float s = 0f;
                for (int f = 0; f < freqs.Length; f++) s += Mathf.Sin(2f * Mathf.PI * freqs[f] * t) / (f + 1);
                d[i] = s * Mathf.Exp(-t * decay);
            }
            Normalize(d, peak);
            return d;
        }

        private static float[] Chime(float[] notes, float noteSeconds)
        {
            var d = Buffer(noteSeconds * notes.Length + 0.35f);
            for (int n = 0; n < notes.Length; n++)
            {
                int start = (int)(n * noteSeconds * SampleRate);
                for (int i = start; i < d.Length; i++)
                {
                    float t = (float)(i - start) / SampleRate;
                    d[i] += (Mathf.Sin(2f * Mathf.PI * notes[n] * t) + 0.3f * Mathf.Sin(4f * Mathf.PI * notes[n] * t)) * Mathf.Exp(-t * 7f);
                }
            }
            Normalize(d, 0.4f);
            return d;
        }

        private static float[] Ko()
        {
            var rng = new System.Random(61);
            var d = Buffer(1.6f);
            float lp = 0f;
            for (int i = 0; i < d.Length; i++)
            {
                float t = (float)i / SampleRate;
                float boom = Mathf.Sin(2f * Mathf.PI * (55f + 40f * Mathf.Exp(-t * 8f)) * t) * Mathf.Exp(-t * 2.2f);
                float tail = Lowpass(ref lp, (float)(rng.NextDouble() * 2 - 1), 700f) * Mathf.Exp(-t * 2.8f);
                d[i] = boom + tail * 0.8f;
            }
            Normalize(d, 0.95f);
            return d;
        }

        private static float[] Ambience(float seconds, float cutoff, float peak, float flutter, int seed)
        {
            var rng = new System.Random(seed);
            var d = Buffer(seconds);
            float lp = 0f;
            for (int i = 0; i < d.Length; i++)
            {
                float t = (float)i / SampleRate;
                float n = Lowpass(ref lp, (float)(rng.NextDouble() * 2 - 1), cutoff);
                float mod = 1f + flutter * Mathf.Sin(2f * Mathf.PI * 0.23f * t) * Mathf.Sin(2f * Mathf.PI * 1.7f * t);
                d[i] = n * mod;
            }
            d = Crossfade(d, 0.25f);
            Normalize(d, peak);
            return d;
        }

        private static float[] Drips(float seconds, int seed)
        {
            var rng = new System.Random(seed);
            var d = Ambience(seconds, 250f, 0.06f, 0f, seed + 1);
            int drops = 14;
            for (int k = 0; k < drops; k++)
            {
                int start = rng.Next(0, d.Length - SampleRate / 4);
                float f0 = 900f + (float)rng.NextDouble() * 900f;
                for (int i = 0; i < SampleRate / 5 && start + i < d.Length; i++)
                {
                    float t = (float)i / SampleRate;
                    d[start + i] += 0.12f * Mathf.Sin(2f * Mathf.PI * (f0 + 2500f * t) * t) * Mathf.Exp(-t * 30f);
                }
            }
            return d;
        }

        /// <summary>Simple original groove: kick, hats and a minor-key bass line, looped for 8 bars.</summary>
        private static float[] Music(int bpm, int[] chordRoots, int rootMidi, float drive, int seed)
        {
            var rng = new System.Random(seed);
            float beat = 60f / bpm;
            int bars = 8;
            var d = Buffer(beat * 4 * bars);
            float lp = 0f, bassLp = 0f;
            int[] minorScale = { 0, 2, 3, 5, 7, 8, 10 };
            for (int i = 0; i < d.Length; i++)
            {
                float t = (float)i / SampleRate;
                float beatPos = t / beat;
                int bar = (int)(beatPos / 4f);
                float inBeat = beatPos - Mathf.Floor(beatPos);
                float eighth = beatPos * 2f - Mathf.Floor(beatPos * 2f);

                // Kick on every beat
                float kt = inBeat * beat;
                float kick = Mathf.Sin(2f * Mathf.PI * (50f + 90f * Mathf.Exp(-kt * 35f)) * kt) * Mathf.Exp(-kt * 9f);
                // Hats on off-beats
                float ht = eighth * beat * 0.5f;
                float hatNoise = (float)(rng.NextDouble() * 2 - 1);
                float hat = ((int)(beatPos * 2f) % 2 == 1) ? (hatNoise - Lowpass(ref lp, hatNoise, 5000f)) * Mathf.Exp(-ht * 60f) : 0f;
                // Bass line follows the chord root, with an octave jump on the off-beat
                int root = chordRoots[bar % chordRoots.Length];
                int degree = minorScale[root % minorScale.Length] + ((int)(beatPos * 2f) % 4 == 3 ? 12 : 0);
                float freq = 440f * Mathf.Pow(2f, (rootMidi + degree - 69) / 12f);
                float saw = 2f * (t * freq - Mathf.Floor(t * freq + 0.5f));
                float bass = Lowpass(ref bassLp, saw, 300f + 500f * drive) * (0.6f + 0.4f * Mathf.Exp(-eighth * 6f));
                d[i] = kick * 0.9f + hat * 0.25f * drive + bass * 0.7f;
            }
            d = Crossfade(d, 0.02f);
            Normalize(d, 0.55f);
            return d;
        }

        /// <summary>Blends the tail into the head and trims the tail, so the loop point is seamless.</summary>
        private static float[] Crossfade(float[] d, float seconds)
        {
            int n = Math.Min(d.Length / 4, (int)(seconds * SampleRate));
            for (int i = 0; i < n; i++)
            {
                float k = (float)i / n;
                int end = d.Length - n + i;
                d[i] = d[i] * k + d[end] * (1f - k);
            }
            var trimmed = new float[d.Length - n];
            Array.Copy(d, trimmed, trimmed.Length);
            return trimmed;
        }
    }
}
